<section class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 fw-bold">Quản lý lịch hẹn</h1><p class="text-secondary mb-0">Xem và cập nhật trạng thái lịch hẹn.</p></div><a class="btn btn-primary" href="<?= e(url('staff.book')) ?>">+ Đặt lịch tại quầy</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Mã</th><th>Bệnh nhân</th><th>Dịch vụ</th><th>Bác sĩ</th><th>Ngày</th><th>Giờ</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody><?php foreach ($appointments as $a): ?><tr><td>#<?= (int)$a['MaLH'] ?></td><td><?= e($a['TenBenhNhan']) ?><br><small class="text-secondary"><?= e($a['SDT']) ?></small></td><td><?= e($a['TenDV']) ?></td><td><?= e($a['TenBacSi']) ?></td><td><?= e($a['NgayKham']) ?></td><td><?= e(substr($a['GioBatDau'],0,5)) ?>–<?= e(substr($a['GioKetThuc'],0,5)) ?></td><td><?= status_badge($a['TrangThai']) ?></td><td><form method="post" action="<?= e(url('staff.appointment.update')) ?>" class="d-flex gap-1"><?= csrf_field() ?><input type="hidden" name="MaLH" value="<?= (int)$a['MaLH'] ?>"><select class="form-select form-select-sm" name="TrangThai"><option value="CHO_XAC_NHAN">Chờ xác nhận</option><option value="DA_XAC_NHAN">Đã xác nhận</option><option value="DA_HUY">Đã hủy</option><option value="DA_HOAN_THANH">Hoàn thành</option></select><button class="btn btn-sm btn-outline-primary">Lưu</button></form></td></tr><?php endforeach; ?><?php if (!$appointments): ?><tr><td colspan="8" class="text-center text-secondary py-4">Chưa có lịch hẹn.</td></tr><?php endif; ?></tbody></table></div></div></section>
